export class Commodity {
  id: number
  name: string
  flowerLanguage: string
  spec: string
  price: number
  imageUrl: string

  constructor(id: number, name: string, flowerLanguage: string, spec: string, price: number, imageUrl: string) {
    this.id = id;
    this.name = name;
    this.flowerLanguage = flowerLanguage;
    this.spec = spec;
    this.price = price;
    this.imageUrl = imageUrl;
  }
}

export class Store {
  id: number
  name: string
  address: string
  phone: string
  lat: number
  lng: number

  constructor(id: number, name: string, address: string, phone: string, lat: number, lng: number) {
    this.id = id;
    this.name = name;
    this.address = address;
    this.phone = phone;
    this.lat = lat;
    this.lng = lng;
  }
}

import { common } from '@kit.AbilityKit';
import { promptAction } from '@kit.ArkUI';
import { Commodity } from '../model/Models';
import { CommodityRepository } from '../data/Repository';
import { PreferencesStore } from '../data/PreferencesStore';
import { PermissionUtil } from '../utils/PermissionUtil';
import { LocationUtil } from '../utils/LocationUtil';
import { ScanUtil } from '../utils/ScanUtil';
import { VoiceUtil } from '../utils/VoiceUtil';
import { MockData } from '../data/MockData';
import { router } from '@kit.ArkUI';

@Entry
@Component
struct Index {
  @State list: Commodity[] = [];
  @State refreshing: boolean = false;
  @State history: Commodity[] = [];
  @State nearby: string = '';
  private repo: CommodityRepository = new CommodityRepository();
  private context: common.UIAbilityContext | null = null;

  aboutToAppear(): void {
    this.context = this.getUIContext().getHostContext() as common.UIAbilityContext;
    this.loadData();
  }

  async loadData(): Promise<void> {
    if (this.context) {
      this.list = await this.repo.fetchList(this.context);
    }
    this.loadHistory();
  }

  async onRefresh(): Promise<void> {
    this.refreshing = true;
    // 模拟网络刷新失败降级：保留现有数据 + 本地缓存
    if (this.context) {
      this.list = await this.repo.fetchList(this.context);
    }
    this.refreshing = false;
  }

  async loadHistory(): Promise<void> {
    if (!this.context) {
      return;
    }
    const ids = await PreferencesStore.getHistory(this.context);
    const all = MockData.commodities();
    const found: (Commodity | undefined)[] = ids.map((id: number) => all.find((c: Commodity) => c.id === id));
    this.history = found.filter((c: Commodity | undefined): boolean => c !== undefined) as Commodity[];
  }

  async onLocate(): Promise<void> {
    if (!this.context) {
      return;
    }
    const granted = await PermissionUtil.request(this.context, [
      'ohos.permission.APPROXIMATELY_LOCATION', 'ohos.permission.LOCATION'
    ]);
    if (!granted) {
      promptAction.showToast({ message: '定位需要位置权限，请在设置中开启' });
      return;
    }
    const loc = await LocationUtil.getCurrent(this.context);
    if (loc) {
      this.nearby = `当前位置：经度 ${loc.lng.toFixed(4)}，纬度 ${loc.lat.toFixed(4)}，附近门店见地图页`;
    } else {
      this.nearby = '获取定位失败';
    }
  }

  async onScan(): Promise<void> {
    if (!this.context) {
      return;
    }
    const raw = await ScanUtil.scan(this.context);
    if (!raw) {
      promptAction.showToast({ message: '扫码未识别或相机不可用' });
      return;
    }
    const id = ScanUtil.parseCommodityId(raw);
    if (id) {
      router.pushUrl({ url: 'pages/CommodityDetail', params: { id } });
    }
  }

  async onVoice(): Promise<void> {
    if (!this.context) {
      return;
    }
    const text = await VoiceUtil.search(this.context);
    if (!text) {
      promptAction.showToast({ message: '语音搜索需要麦克风权限' });
      return;
    }
    const hit = MockData.commodities().find(c => c.name === text);
    if (hit) {
      router.pushUrl({ url: 'pages/CommodityDetail', params: { id: hit.id } });
    } else {
      promptAction.showToast({ message: `未找到「${text}」相关商品` });
    }
  }

  @Builder
  TopBar() {
    Row({ space: 8 }) {
      Text('花语')
        .fontSize(22)
        .fontWeight(FontWeight.Bold)
        .layoutWeight(1)
      Button('扫码')
        .onClick(() => this.onScan())
      Button('语音')
        .onClick(() => this.onVoice())
    }
    .width('100%')
    .padding(12)
  }

  build() {
    Column() {
      this.TopBar()
      Refresh({ refreshing: this.refreshing }) {
        List() {
          ForEach(this.list, (item: Commodity) => {
            ListItem() {
              this.CommodityCard(item)
            }
          }, (item: Commodity) => item.id.toString())
        }
      }
      .onRefreshing(() => this.onRefresh())
      .layoutWeight(1)

      Row({ space: 8 }) {
        Button('定位')
          .onClick(() => this.onLocate())
        Button('地图')
          .onClick(() => router.pushUrl({ url: 'pages/StoreMap' }))
      }
      .padding(12)

      if (this.nearby.length > 0) {
        Text(this.nearby)
          .fontSize(13)
          .padding(8)
      }

      Text('最近浏览')
        .fontSize(16)
        .fontWeight(FontWeight.Medium)
        .width('100%')
        .padding({ left: 12, top: 8, bottom: 4 })
      List() {
        ForEach(this.history, (item: Commodity) => {
          ListItem() {
            this.CommodityCard(item, true)
          }
        }, (item: Commodity) => `h${item.id}`)
      }
      .height(this.history.length > 0 ? 160 : 0)

      Row({ space: 12 }) {
        Button('我的')
          .onClick(() => router.pushUrl({ url: 'pages/Personal' }))
        Button('支付安全')
          .onClick(() => router.pushUrl({ url: 'pages/PaySecurity' }))
      }
      .padding(12)
    }
    .width('100%')
    .height('100%')
  }

  @Builder
  CommodityCard(item: Commodity, compact: boolean = false) {
    Row({ space: 10 }) {
      Image($r('app.media.startIcon'))
        .width(compact ? 48 : 64)
        .height(compact ? 48 : 64)
        .alt(item.name)
      Column({ space: 4 }) {
        Text(item.name)
          .fontSize(16)
          .fontWeight(FontWeight.Medium)
          .accessibilityText(item.name)
        Text(item.flowerLanguage)
          .fontSize(12)
          .fontColor(Color.Gray)
        Row() {
          Text(`¥${item.price.toFixed(2)}`)
            .fontSize(15)
            .fontColor('#E53935')
            .accessibilityText(`价格 ${item.price} 元`)
        }
      }
      .layoutWeight(1)
      .alignItems(HorizontalAlign.Start)
    }
    .padding(10)
    .backgroundColor(Color.White)
    .borderRadius(8)
    .margin({ bottom: 8 })
    .onClick(() => {
      if (this.context) {
        PreferencesStore.recordBrowse(this.context, item.id);
      }
      router.pushUrl({ url: 'pages/CommodityDetail', params: { id: item.id } });
    })
  }
}

import { common } from '@kit.AbilityKit';
import { promptAction, router } from '@kit.ArkUI';
import { Commodity } from '../model/Models';
import { CommodityRepository } from '../data/Repository';
import { PreferencesStore } from '../data/PreferencesStore';
import { NotificationUtil } from '../utils/NotificationUtil';
import { ShareUtil } from '../utils/ShareUtil';
import { CalendarUtil } from '../utils/CalendarUtil';
import { SmartVaseUtil } from '../utils/SmartVaseUtil';
import { ImagePickerUtil } from '../utils/ImagePickerUtil';
import { MockData } from '../data/MockData';

@Entry
@Component
struct CommodityDetail {
  @State commodity: Commodity | null = null;
  @State favorite: boolean = false;
  @State pickedImages: string[] = [];
  @State receiver: string = '收货人：张女士';
  private context: common.UIAbilityContext | null = null;
  private repo: CommodityRepository = new CommodityRepository();

  aboutToAppear(): void {
    this.context = this.getUIContext().getHostContext() as common.UIAbilityContext;
    const params = router.getParams() as Record<string, number>;
    const id = params && params['id'] ? params['id'] : 1;
    this.load(id);
  }

  async load(id: number): Promise<void> {
    if (this.context) {
      this.commodity = await this.repo.fetchDetail(this.context, id);
      this.favorite = (await PreferencesStore.getFavorites(this.context)).includes(id);
      PreferencesStore.recordBrowse(this.context, id);
    }
  }

  async toggleFavorite(): Promise<void> {
    if (!this.context || !this.commodity) {
      return;
    }
    this.favorite = !this.favorite;
    await PreferencesStore.setFavorite(this.context, this.commodity.id, this.favorite);
    promptAction.showToast({ message: this.favorite ? '已收藏' : '已取消收藏' });
  }

  async onBuy(): Promise<void> {
    if (!this.context || !this.commodity) {
      return;
    }
    const sent = await NotificationUtil.sendOrder(this.context, this.commodity.name);
    if (!sent) {
      promptAction.showToast({ message: '通知已关闭，可在设置中开启' });
    }
    // 跳转支付页（功能预留）
    router.pushUrl({ url: 'pages/PaySecurity' });
  }

  async onCalendar(): Promise<void> {
    if (!this.context || !this.commodity) {
      return;
    }
    const ok = await CalendarUtil.addReminder(this.context, this.commodity.name, this.receiver);
    promptAction.showToast({ message: ok ? '已添加配送日历提醒' : '添加日历需要日历权限，请在设置中开启' });
  }

  async onShare(): Promise<void> {
    if (this.commodity) {
      await ShareUtil.share(this.context as common.UIAbilityContext, this.commodity.name, this.commodity.price);
    }
  }

  async onSmartVase(): Promise<void> {
    await SmartVaseUtil.queryStatus();
  }

  async onPickImage(): Promise<void> {
    const uris = await ImagePickerUtil.pick();
    if (uris.length > 0) {
      this.pickedImages = this.pickedImages.concat(uris);
    }
  }

  @Builder
  ServiceCard() {
    Column({ space: 8 }) {
      Text('优惠与服务')
        .fontSize(15)
        .fontWeight(FontWeight.Medium)
      Row({ space: 8 }) {
        Button('配送日历')
          .onClick(() => this.onCalendar())
        Button('分享好友')
          .onClick(() => this.onShare())
      }
      Row({ space: 8 }) {
        Button('智能花瓶')
          .onClick(() => this.onSmartVase())
        Button('晒图评价')
          .onClick(() => this.onPickImage())
      }
      if (this.pickedImages.length > 0) {
        Row({ space: 6 }) {
          ForEach(this.pickedImages, (uri: string) => {
            Image(uri)
              .width(48)
              .height(48)
          }, (uri: string, i: number) => `${uri}_${i}`)
        }
        Button('删除已选')
          .fontSize(13)
          .onClick(() => this.pickedImages = [])
      }
      Text(`· ${this.receiver} · 支付安全见「支付安全」页 · 客服预留`)
        .fontSize(12)
        .fontColor(Color.Gray)
    }
    .width('100%')
    .padding(12)
    .backgroundColor('#F5F5F5')
    .borderRadius(8)
  }

  build() {
    Column() {
      if (this.commodity) {
        Scroll() {
          Column({ space: 12 }) {
            Image($r('app.media.startIcon'))
              .width('100%')
              .height(240)
              .alt(this.commodity.name)
              .borderRadius(8)

            Row({ space: 8 }) {
              Text(this.commodity.name)
                .fontSize(22)
                .fontWeight(FontWeight.Bold)
                .layoutWeight(1)
                .accessibilityText(this.commodity.name)
              Button(this.favorite ? '♥ 已收藏' : '♡ 收藏')
                .fontSize(14)
                .onClick(() => this.toggleFavorite())
                .accessibilityText(this.favorite ? '已收藏' : '未收藏')
            }
            .width('100%')

            Text(`¥${this.commodity.price.toFixed(2)}`)
              .fontSize(24)
              .fontColor('#E53935')
              .accessibilityText(`价格 ${this.commodity.price} 元`)

            Text(`花语：${this.commodity.flowerLanguage}`)
              .fontSize(15)
            Text(`规格：${this.commodity.spec}`)
              .fontSize(14)
              .fontColor(Color.Gray)

            this.ServiceCard()
          }
          .padding(12)
        }
        .layoutWeight(1)

        Row({ space: 8 }) {
          Button('客服')
            .fontSize(14)
            .onClick(() => promptAction.showToast({ message: '客服功能预留' }))
          Button('立即购买')
            .fontSize(16)
            .fontWeight(FontWeight.Medium)
            .layoutWeight(1)
            .onClick(() => this.onBuy())
        }
        .width('100%')
        .padding(12)
        .backgroundColor(Color.White)
      } else {
        Text('商品加载中…')
          .fontSize(16)
          .margin({ top: 60 })
      }
    }
    .width('100%')
    .height('100%')
  }
}
